async function allBases(){return Promise.all(catalog.map(c=>get(`/editor/data/${c.stage}.json`)));}
async function collectPack(){
 await save();const drafts={...publishedProjects};
 for(const c of catalog){const raw=await draftStore.get(storageKey(c.stage));if(raw){try{drafts[c.stage]=JSON.parse(raw);}catch{throw Error(`${c.character}: saved draft cannot be read. Export or repair it before building all levels.`);}}}
 if(project)drafts[project.stage]=clone(project);
 const pack=createStagePack(await allBases(),drafts,project?.stage);
 if(new Blob([JSON.stringify(pack)]).size>PACK_LIMIT)throw Error('Level pack must be under 128 MB.');return pack;
}
function downloadPack(pack){const url=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)+'\n'],{type:'application/json'})),a=el('a');a.href=url;a.download='Custom-Melee-BTT-all-levels.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
