 if(incoming?.format!=='TTRC_STAGE_PACK'){
  if(!catalog.some(c=>c.stage===incoming?.stage))throw Error('Unknown stage.');
  await load(incoming.stage,incoming);toast("Imported project. Click Test in Dolphin to play it.");return;
 }
 const errors=validateStagePack(incoming,await allBases());if(errors.length)throw Error(errors.join(' '));
 await save();const previous=new Map();
 try{
  for(const p of incoming.projects){const key=storageKey(p.stage),raw=await draftStore.get(key);previous.set(key,raw);previous.set(key+':older',await draftStore.get(key+':older'));if(raw&&raw!==JSON.stringify(p))await draftStore.set(key+':older',raw);await draftStore.set(key,JSON.stringify(p));}
 }catch(error){for(const [key,raw]of previous){try{if(raw===null)await draftStore.remove(key);else await draftStore.set(key,raw);}catch{}}throw Error('Not enough browser storage to import all levels. Keep the exported file.');}
 project=null;await load(catalog.some(c=>c.stage===incoming.activeStage)?incoming.activeStage:incoming.projects[0].stage);
