async function packAction(button,action){
 if(!project||busy)return;busy=true;const label=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Preparing all levels…';
 try{await action(await collectPack());}catch(e){toast(e.message);}finally{busy=false;button.disabled=false;button.removeAttribute('aria-busy');button.textContent=label;checks();}
}
$('export-all').onclick=()=>packAction($('export-all'),async pack=>{downloadPack(pack);toast(`${pack.projects.length} levels exported.`);});
$('build-all').onclick=()=>packAction($('build-all'),async pack=>{
 if(!local){
  const fragment='#draft='+encodeURIComponent(JSON.stringify(pack));
  if(fragment.length>1600000){downloadPack(pack);window.open('http://localhost:4317/editor','_blank','noopener');toast('Open the exported level pack in your companion, then click Build all in Dolphin.');return;}
  window.open('http://localhost:4317/editor'+fragment,'_blank','noopener');toast('All levels sent to your companion. Click Build all in Dolphin there to launch.');return;
 }
 $('build-all').textContent='Building all levels…';
 const r=await fetch('/api/editor/build-all',{method:'POST',headers:{'Content-Type':'application/json','X-TTRC-Action':'launch'},body:JSON.stringify(pack)}),data=await r.json();
 if(!r.ok)throw Error(data.error||'Could not build the level pack.');
 toast(data.status==='already-running'?'Close the Custom Melee BTT game window, then build again.':`${pack.projects.length} levels built. Choose any character in Target Test.`);
});
$('export').onclick=()=>{if(!project)return;const blob=new Blob([JSON.stringify(project,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=project.name.replace(/[^a-z0-9_-]/gi,'-')+'.ttrc.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Project exported.');};
$('import').onclick=()=>$('project-file').click();$('project-file').onchange=async()=>{const file=$('project-file').files[0];$('project-file').value='';if(!file)return;if(file.size>PACK_LIMIT)return toast('Project files must be under 128 MB.');try{const p=JSON.parse(await file.text());await importDocument(p);}catch(e){toast(e.message);}};
$('preview').onclick=()=>{if(placingStops!==null)stopPlacement();playing=!playing;$('preview').textContent=playing?'Ⅱ Pause preview':'▶ Preview motion';};$('frame').oninput=()=>{playing=false;frame=Number($('frame').value);$('preview').textContent='▶ Preview motion';draw();};
function tick(now){if(playing&&project){frame=(frame+(now-last)*.06)%Number($('frame').max);draw();}last=now;requestAnimationFrame(tick);}requestAnimationFrame(tick);
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();space=true;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('redo'):$('undo')).click();}if(e.key==='Escape'){if(placingStops!==null){stopPlacement();return;}selection=null;renderUI();}if(project&&selection&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const n=Number($('grid').value)*(e.shiftKey?5:1);moveSelection(project,selection,e.key==='ArrowRight'?n:e.key==='ArrowLeft'?-n:0,e.key==='ArrowUp'?n:e.key==='ArrowDown'?-n:0,base);commit();}});document.addEventListener('keyup',e=>{if(e.code==='Space')space=false;});window.addEventListener('blur',()=>{space=false;release();});
$('test').onclick=async()=>{if(!project||checks().length||busy)return;if(!local){save();const fragment='#draft='+encodeURIComponent(JSON.stringify(project));if(fragment.length>1600000){$('export').click();window.open('http://localhost:4317/editor','_blank','noopener');toast('Project with textures exported. Open that file in your companion, then click Test in Dolphin.');return;}window.open('http://localhost:4317/editor'+fragment,'_blank','noopener');toast('Project sent in the link. In your running companion, click Test in Dolphin to launch it.');return;}busy=true;$('test').disabled=true;$('test').setAttribute('aria-busy','true');$('test').textContent='Building stage…';save();try{const r=await fetch('/api/editor/test',{method:'POST',headers:{'Content-Type':'application/json','X-TTRC-Action':'launch'},body:JSON.stringify(project)});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not build this stage.');toast(data.status==='already-running'?'Close the Custom Melee BTT game window, then test again.':`Dolphin opened. Press Start to play ${base.character}${base.stage==='Sk'?' (hold A for Sheik)':''}.`);}catch(e){toast(e.message);}finally{busy=false;$('test').removeAttribute('aria-busy');$('test').textContent='Test in Dolphin ↗';checks();}};
try{[catalog,additionCatalog]=await Promise.all([get('/editor/data/catalog.json'),get('/editor/data/models/additions.json')]);for(const c of catalog){const option=el('option',c.character+' · '+c.name);option.value=c.stage;$('stage').append(option);}$('stage').disabled=false;try{const r=await fetch('/api/editor/status');if(r.ok){const info=await r.json();local=!!info.available;}}catch{}$('companion-link').hidden=local;if(!local)$('test').title='Transfer this draft to your running local Custom Melee BTT Companion.';const published=await get('/editor/published-levels.json');publishedProjects=Object.fromEntries(published.projects.map(p=>[p.stage,p]));let incoming=null;try{if(location.hash.startsWith('#draft=')){incoming=JSON.parse(decodeURIComponent(location.hash.slice(7)));if(JSON.stringify(incoming).length>8*1024*1024)throw Error('Shared project is too large.');window.history.replaceState(null,'',location.pathname);}}catch(e){toast('Could not open shared project: '+e.message);incoming=null;}let initial=incoming?.stage||'Pk';try{if(!incoming)initial=localStorage.getItem('ttrc-editor-stage')||initial;}catch{}if(incoming)await importDocument(incoming);else await load(catalog.some(c=>c.stage===initial)?initial:'Pk');}catch(e){$('loading').querySelector('p').textContent=e.message;$('retry').hidden=false;$('retry').onclick=()=>location.reload();}

window.addEventListener('hashchange',async()=>{if(!location.hash.startsWith('#draft='))return;try{if(location.hash.length>24000000)throw Error('Shared project is too large.');const incoming=JSON.parse(decodeURIComponent(location.hash.slice(7)));window.history.replaceState(null,'',location.pathname);await importDocument(incoming);}catch(e){toast('Could not open shared project: '+e.message);}});
